    'Compare with previous period': ['Porównaj z poprzednim okresem', 'Mit vorherigem Zeitraum vergleichen', 'Comparar con el período anterior', 'Comparer à la période précédente', 'Comparar com o período anterior'],
    'Update preview': ['Odśwież podgląd', 'Vorschau aktualisieren', 'Actualizar vista previa', 'Actualiser l’aperçu', 'Atualizar pré-visualização'],
    'Export PDF': ['Eksportuj PDF', 'PDF exportieren', 'Exportar PDF', 'Exporter en PDF', 'Exportar PDF'],
